pico-blink.source:
void setup() {
  pinMode(LED_BUILTIN, OUTPUT);
  pinMode(15, OUTPUT);
}

void loop() {
  digitalWrite(LED_BUILTIN, HIGH);
  digitalWrite(15, HIGH);
  delay(100);
  digitalWrite(LED_BUILTIN, LOW);
  digitalWrite(15, LOW);
  delay(100);
}

pico-io.source:
void setup() {
  Serial.begin(115200);
  pinMode(16, INPUT_PULLUP);
  pinMode(14, OUTPUT);
  analogWrite(13, 128);
}

void loop() {
  int a = analogRead(A0);
  int b = digitalRead(16);
  digitalWrite(14, b ? LOW : HIGH);
  Serial.print("adc=");
  Serial.print(a);
  Serial.print(" btn=");
  Serial.println(b);
  delay(50);
}

pico-serial1.source:
// Pico: Serial1 (UART0, TX = GP0, RX = GP1) says hello, and echoes what it hears
void setup() { Serial1.begin(9600); Serial1.println("hello from pico"); }
void loop() { while (Serial1.available()) Serial1.write(Serial1.read()); }
